import React, { useState, useEffect } from 'react';
import {
  Grid, Card, CardContent, Typography, Button, TextField, Select, MenuItem,
  FormControl, InputLabel, Paper, Box, IconButton, Chip, Divider, Snackbar, Alert, InputAdornment, Stack
} from '@mui/material';
import { Add, Remove, Delete, ShoppingCart, Search, ClearAll } from '@mui/icons-material';
import Layout from '../components/Layout';
import { menuService, orderService, categoryService } from '../services/api';

const POS = () => {
  const [menuItems, setMenuItems] = useState([]);
  const [categories, setCategories] = useState([]);
  const [filteredMenuItems, setFilteredMenuItems] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('ALL');
  const [cart, setCart] = useState([]);
  const [paymentMethod, setPaymentMethod] = useState('CASH');
  const [discountPercent, setDiscountPercent] = useState('');
  const [message, setMessage] = useState({ type: '', text: '' });



  const loadData = async () => {
    try {
      const [menuRes, catRes] = await Promise.all([
        menuService.getActive(),
        categoryService.getAll()
      ]);
      setMenuItems(menuRes.data.data);
      setCategories(catRes.data.data);
      setFilteredMenuItems(menuRes.data.data);
    } catch (error) {
      setMessage({ type: 'error', text: error.response?.data?.message || 'Failed to load data' });
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    let result = menuItems;

    // Filter by Category
    if (selectedCategory !== 'ALL') {
      result = result.filter(item => item.categoryId === selectedCategory);
    }

    // Filter by Search Query
    if (searchQuery.trim() !== '') {
      result = result.filter(item =>
        item.name.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    setFilteredMenuItems(result);
  }, [searchQuery, selectedCategory, menuItems]);

  const addToCart = (item) => {
    const existing = cart.find(c => c.menuItemId === item.id);
    if (existing) {
      setCart(cart.map(c => 
        c.menuItemId === item.id ? { ...c, quantity: c.quantity + 1 } : c
      ));
    } else {
      setCart([...cart, {
        menuItemId: item.id,
        menuItemName: item.name,
        price: item.price,
        quantity: 1
      }]);
    }
  };

  const updateQuantity = (menuItemId, delta) => {
    setCart(cart.map(item => {
      if (item.menuItemId === menuItemId) {
        const newQty = item.quantity + delta;
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const removeFromCart = (menuItemId) => {
    setCart(cart.filter(item => item.menuItemId !== menuItemId));
  };

  const clearCart = () => {
    if (cart.length === 0) return;
    setCart([]);
    setDiscountPercent('');
    setMessage({ type: 'info', text: 'Cart cleared' });
  };

  const calculateTotal = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const discountVal = parseFloat(discountPercent) || 0;
    const discountAmount = (subtotal * discountVal) / 100;
    const taxableAmount = Math.max(0, subtotal - discountAmount);
    const tax = taxableAmount * 0.05;
    return {
      subtotal: subtotal.toFixed(2),
      discount: discountAmount.toFixed(2),
      tax: tax.toFixed(2),
      total: (taxableAmount + tax).toFixed(2)
    };
  };

  const handleCheckout = async () => {
    if (cart.length === 0) {
      setMessage({ type: 'error', text: 'Cart is empty' });
      return;
    }

    const totals = calculateTotal();
    const order = {
      items: cart,
      discount: parseFloat(totals.discount),
      payment: {
        method: paymentMethod,
        amount: parseFloat(totals.total)
      }
    };

    try {
      await orderService.create(order);
      setMessage({ type: 'success', text: 'Order created successfully!' });
      setCart([]);
      setDiscountPercent('');
    } catch (error) {
      setMessage({ type: 'error', text: error.response?.data?.message || 'Failed to create order' });
    }
  };

  const handleCloseToast = (event, reason) => {
    if (reason === 'clickaway') {
      return;
    }
    setMessage({ type: '', text: '' });
  };

  const totals = calculateTotal();

  return (
    <Layout 
      title="Point of Sale" 
      headerContent={
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Typography variant="h5" fontWeight="bold" color="primary">
            Menu Items
          </Typography>
          <Chip 
            icon={<ShoppingCart />} 
            label={`${cart.length} items`} 
            color="primary" 
            variant="outlined"
          />
        </Box>
      }
    >
      <Snackbar
        open={!!message.text}
        autoHideDuration={6000}
        onClose={handleCloseToast}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <Alert 
          onClose={handleCloseToast} 
          severity={message.type || 'info'}
          variant="filled"
          sx={{ width: '100%' }}
        >
          {message.text}
        </Alert>
      </Snackbar>

      <Grid container spacing={3}>
        {/* Menu Items Section */}
        <Grid item xs={12} md={8}>

          <Stack direction="row" spacing={1} sx={{ mb: 2, overflowX: 'auto', pb: 1 }}>
            <Chip 
              label="All" 
              onClick={() => setSelectedCategory('ALL')}
              color={selectedCategory === 'ALL' ? "primary" : "default"}
              variant={selectedCategory === 'ALL' ? "filled" : "outlined"}
              clickable
            />
            {categories.map(cat => (
              <Chip
                key={cat.id}
                label={cat.name}
                onClick={() => setSelectedCategory(cat.id)}
                color={selectedCategory === cat.id ? "primary" : "default"}
                variant={selectedCategory === cat.id ? "filled" : "outlined"}
                clickable
              />
            ))}
          </Stack>

          <TextField
            fullWidth
            placeholder="Search menu items..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            sx={{ mb: 4 }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <Search sx={{ color: 'text.secondary' }} />
                </InputAdornment>
              ),
            }}
            variant="outlined"
            size="small"
          />
          
          <Box
            sx={{
              maxHeight: 'calc(100vh - 250px)',
              overflowY: 'auto',
              pr: 1,
              '&::-webkit-scrollbar': {
                width: '6px',
              },
              '&::-webkit-scrollbar-track': {
                backgroundColor: 'background.default',
                borderRadius: '3px',
              },
              '&::-webkit-scrollbar-thumb': {
                backgroundColor: 'text.secondary',
                borderRadius: '3px',
                '&:hover': {
                  backgroundColor: 'text.primary',
                },
              },
            }}
          >
            <Grid container spacing={2} sx={{ p: 1 }}>
            {filteredMenuItems.map(item => (
              <Grid item xs={6} sm={6} md={6} lg={4} key={item.id}>
                <Card 
                  sx={{ 
                    height: '100%',
                    display: 'flex',
                    flexDirection: 'column',
                    borderRadius: 3,
                    overflow: 'hidden',
                    transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                    cursor: 'default',
                    border: '1px solid',
                    borderColor: 'divider',
                    boxShadow: 2,
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 8,
                      borderColor: 'primary.main',
                      '& .item-image': {
                        transform: 'scale(1.1)'
                      }
                    }
                  }}
                >
                  {/* Square Image Container */}
                  <Box
                    sx={{
                      width: '100%',
                      height: 200,
                      overflow: 'hidden',
                      backgroundColor: '#f5f5f5',
                      position: 'relative',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center'
                    }}
                  >
                    {item.imageUrl ? (
                      <img
                        className="item-image"
                        src={item.imageUrl}
                        alt={item.name}
                        style={{
                          width: '100%',
                          height: '100%',
                          objectFit: 'cover',
                          objectPosition: 'center',
                          display: 'block',
                          transition: 'transform 0.5s ease'
                        }}
                        onError={(e) => {
                          e.target.src = 'https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=400';
                        }}
                      />
                    ) : (
                      <Box
                        sx={{
                          width: '100%',
                          height: '100%',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          backgroundColor: '#e0e0e0',
                          color: '#9e9e9e',
                          aspectRatio: '1 / 1'
                        }}
                      >
                        <Typography variant="body2">No Image</Typography>
                      </Box>
                    )}
                  </Box>

                  {/* Card Content */}
                  <CardContent 
                    sx={{ 
                      flexGrow: 1,
                      display: 'flex',
                      flexDirection: 'column',
                      p: 1.5,
                      pt: 1.5,
                      '&:last-child': {
                        pb: 1.5
                      }
                    }}
                  >
                    <Typography 
                      variant="subtitle2" 
                      fontWeight="bold"
                      sx={{ 
                        fontSize: '0.875rem',
                        lineHeight: 1.3,
                        mb: 0.5,
                        display: '-webkit-box',
                        WebkitLineClamp: 2,
                        WebkitBoxOrient: 'vertical',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        minHeight: '2.6rem'
                      }}
                    >
                      {item.name}
                    </Typography>
                    
                    <Typography 
                      variant="h6" 
                      color="primary"
                      fontWeight="bold"
                      sx={{ 
                        fontSize: '1rem',
                        mt: 'auto',
                        mb: 0.5
                      }}
                    >
                      ₹{Number(item.price).toFixed(2)}
                    </Typography>
                    
                      {cart.find(c => c.menuItemId === item.id) ? (
                        <Box 
                          sx={{ 
                            display: 'flex', 
                            alignItems: 'center', 
                            justifyContent: 'center',
                            gap: 1,
                            border: '1px solid',
                            borderColor: 'divider',
                            borderRadius: 1,
                            p: 0.5,
                            px: 2,
                            width: 'fit-content',
                            ml: 'auto'
                          }}
                          onClick={(e) => e.stopPropagation()}
                        >
                          <IconButton 
                            size="small" 
                            onClick={(e) => {
                              e.stopPropagation();
                              updateQuantity(item.id, -1);
                            }}
                            sx={{ p: 0.5 }}
                          >
                            <Remove fontSize="small" />
                          </IconButton>
                          <Typography fontWeight="bold">
                            {cart.find(c => c.menuItemId === item.id).quantity}
                          </Typography>
                          <IconButton 
                            size="small" 
                            onClick={(e) => {
                              e.stopPropagation();
                              updateQuantity(item.id, 1);
                            }}
                            sx={{ p: 0.5 }}
                          >
                            <Add fontSize="small" />
                          </IconButton>
                        </Box>
                      ) : (
                        <Button
                          fullWidth
                          variant="contained"
                          size="small"
                          onClick={(e) => {
                            e.stopPropagation();
                            addToCart(item);
                          }}
                          sx={{ 
                            py: 0.75,
                            fontSize: '0.75rem',
                            textTransform: 'none',
                            fontWeight: 'bold',
                            borderRadius: 1
                          }}
                        >
                          Add to Cart
                        </Button>
                      )}
                  </CardContent>
                </Card>
              </Grid>
            ))}
            </Grid>
          </Box>
        </Grid>

        {/* Cart Section */}
        <Grid item xs={12} md={4}>
          <Paper 
            sx={{ 
              p: 3,
              borderRadius: 2,
              boxShadow: 3,
              display: 'flex',
              flexDirection: 'column',
              position: { xs: 'relative', md: 'sticky' },
              top: { md: 100 },
              height: { xs: 'auto', md: 'calc(100vh - 120px)' },
              maxHeight: { xs: '80vh', md: 'calc(100vh - 120px)' }
            }}
          >
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
              <Typography variant="h5" fontWeight="bold" color="primary">
                Current Order
              </Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                {cart.length > 0 && (
                  <>
                    <Chip 
                      label={`${cart.reduce((sum, item) => sum + item.quantity, 0)} items`}
                      color="primary"
                      size="small"
                    />
                    <Button
                      variant="outlined"
                      color="error"
                      size="small"
                      startIcon={<ClearAll />}
                      onClick={clearCart}
                      sx={{
                        textTransform: 'none',
                        fontSize: '0.75rem',
                        py: 0.5,
                        px: 1.5
                      }}
                    >
                      Clear All
                    </Button>
                  </>
                )}
              </Box>
            </Box>
            
            <Divider sx={{ mb: 2 }} />

            {/* Cart Items */}
            <Box 
              sx={{ 
                flex: 1,
                overflowY: 'auto',
                mb: 2,
                minHeight: 0,
                pr: 1,
                '&::-webkit-scrollbar': {
                  width: '6px',
                },
                '&::-webkit-scrollbar-track': {
                  backgroundColor: 'background.default',
                  borderRadius: '3px',
                },
                '&::-webkit-scrollbar-thumb': {
                  backgroundColor: 'text.secondary',
                  borderRadius: '3px',
                  '&:hover': {
                    backgroundColor: 'text.primary',
                  },
                },
              }}
            >
              {cart.length === 0 ? (
                <Box sx={{ textAlign: 'center', py: 4 }}>
                  <ShoppingCart sx={{ fontSize: 48, color: 'text.secondary', mb: 1 }} />
                  <Typography variant="body1" color="text.secondary">
                    Your cart is empty
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                    Add items from the menu
                  </Typography>
                </Box>
              ) : (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
                  {cart.map(item => (
                    <Paper
                      key={item.menuItemId}
                      sx={{
                        p: 1.5,
                        display: 'flex',
                        alignItems: 'center',
                        gap: 1,
                        backgroundColor: 'background.paper',
                        border: '1px solid',
                        borderColor: 'divider',
                        borderRadius: 1,
                        transition: 'all 0.2s',
                        '&:hover': {
                          boxShadow: 2,
                          borderColor: 'primary.main'
                        }
                      }}
                    >
                      <Box sx={{ flexGrow: 1, minWidth: 0, mr: 1 }}>
                        <Typography 
                          variant="subtitle2" 
                          fontWeight="bold"
                          sx={{
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap'
                          }}
                        >
                          {item.menuItemName}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          ₹{Number(item.price).toFixed(2)} each
                        </Typography>
                      </Box>
                      
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <Typography 
                          variant="body1" 
                          fontWeight="bold" 
                          sx={{ 
                            minWidth: '32px', 
                            textAlign: 'center',
                            fontSize: '0.95rem'
                          }}
                        >
                          x{item.quantity}
                        </Typography>
                      </Box>
                      
                      <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', ml: 1, minWidth: '90px' }}>
                        <Typography variant="subtitle2" fontWeight="bold" color="primary" sx={{ mb: 0.5 }}>
                          ₹{(item.price * item.quantity).toFixed(2)}
                        </Typography>
                        <IconButton 
                          size="small" 
                          onClick={() => removeFromCart(item.menuItemId)}
                          sx={{ 
                            color: 'error.main',
                            width: 28,
                            height: 28,
                            '&:hover': { 
                              backgroundColor: 'error.light', 
                              color: 'error.dark' 
                            }
                          }}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </Box>
                    </Paper>
                  ))}
                </Box>
              )}
            </Box>

            <Divider sx={{ my: 2 }} />

            {/* Payment Section */}
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, flexShrink: 0 }}>
              <TextField
                fullWidth
                label="Discount (%)"
                type="number"
                value={discountPercent}
                onChange={(e) => {
                  const val = e.target.value;
                  // Allow empty string to clear the field
                  if (val === '') {
                    setDiscountPercent('');
                    return;
                  }
                  const numVal = parseFloat(val);
                  if (numVal >= 0 && numVal <= 100) {
                    setDiscountPercent(val);
                  }
                }}
                size="small"
                InputProps={{
                  inputProps: { min: 0, max: 100, step: 1 }
                }}
              />

              <FormControl fullWidth size="small">
                <InputLabel>Payment Method</InputLabel>
                <Select
                  value={paymentMethod}
                  onChange={(e) => setPaymentMethod(e.target.value)}
                  label="Payment Method"
                >
                  <MenuItem value="CASH">Cash</MenuItem>
                  <MenuItem value="CARD">Card</MenuItem>
                  <MenuItem value="UPI">UPI</MenuItem>
                </Select>
              </FormControl>

              {/* Totals */}
              <Box 
                sx={{ 
                  p: 2,
                  backgroundColor: 'background.default',
                  borderRadius: 1,
                  border: '1px solid',
                  borderColor: 'divider'
                }}
              >
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                  <Typography variant="body2" color="text.secondary">Subtotal:</Typography>
                  <Typography variant="body2" fontWeight="medium">₹{totals.subtotal}</Typography>
                </Box>
                {parseFloat(totals.discount) > 0 && (
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                    <Typography variant="body2" color="text.secondary">Discount:</Typography>
                    <Typography variant="body2" color="success.main" fontWeight="medium">
                      -₹{totals.discount}
                    </Typography>
                  </Box>
                )}
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                  <Typography variant="body2" color="text.secondary">Tax (5%):</Typography>
                  <Typography variant="body2" fontWeight="medium">₹{totals.tax}</Typography>
                </Box>
                <Divider sx={{ my: 1 }} />
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Typography variant="h6" fontWeight="bold">Total:</Typography>
                  <Typography variant="h6" fontWeight="bold" color="primary">
                    ₹{totals.total}
                  </Typography>
                </Box>
              </Box>

              <Button
                fullWidth
                variant="contained"
                color="primary"
                size="large"
                onClick={handleCheckout}
                disabled={cart.length === 0}
                sx={{
                  py: 1.5,
                  fontSize: '1rem',
                  fontWeight: 'bold',
                  borderRadius: 1,
                  textTransform: 'none',
                  boxShadow: 2,
                  '&:hover': {
                    boxShadow: 4
                  },
                  '&:disabled': {
                    opacity: 0.6
                  }
                }}
              >
                Complete Order
              </Button>
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Layout>
  );
};

export default POS;
